113	// renames it over the target, so a reader never sees half a file.
114	func writeFileAtomic(path string, data []byte) error {
115		tmp, err := os.CreateTemp(filepath.Dir(path), filepath.Base(path)+".*")
116		if err != nil {
117			return err
118		}
119		name := tmp.Name()
120		if _, err := tmp.Write(data); err != nil {
121			_ = tmp.Close()
122			_ = os.Remove(name)
123			return err
124		}
125		if err := tmp.Close(); err != nil {
126			_ = os.Remove(name)
127			return err
128		}
129		if err := os.Chmod(name, 0o600); err != nil {
130			_ = os.Remove(name)
131			return err
132		}
133		if err := os.Rename(name, path); err != nil {
134			_ = os.Remove(name)
135			return err
136		}
137		return nil
138	}
